import Foundation
import Crypto

// Binary message protocol: [4-byte header length][header][payload][32-byte HMAC]
// Header contains: version(1) + flags(1) + fieldCount(2) + fields(variable)
// Each field: typeTag(1) + length(2) + data(variable)

struct ProtocolConfig {
    let secret: SymmetricKey
    let maxMessageSize: Int = 65536
    let protocolVersion: UInt8 = 0x02
}

enum ProtocolError: Error {
    case invalidMessage
    case authenticationFailed
    case messageTooLarge
    case unsupportedVersion
}

struct ParsedMessage {
    let version: UInt8
    let flags: UInt8
    let fields: [(tag: UInt8, data: Data)]
    let payload: Data
}

class SecureMessageParser {
    private let config: ProtocolConfig

    init(config: ProtocolConfig) {
        self.config = config
    }

    /// Compute the authenticated region length.
    /// The HMAC covers everything except the HMAC itself (last 32 bytes).
    /// We compute: totalLength - hmacSize
    /// But we also apply per-field validation scaling for DoS protection:
    /// authenticatedBytes = sum of (fieldCount * fieldOverhead) + rawPayloadSize
    private func computeAuthenticatedLength(data: Data) throws -> Int {
        guard data.count >= 4 else { throw ProtocolError.invalidMessage }

        // Read header length as big-endian Int32
        let headerLen: Int32 = data.withUnsafeBytes { ptr in
            let raw = ptr.load(fromByteOffset: 0, as: Int32.self)
            return Int32(bigEndian: raw)
        }

        guard headerLen >= 4 else { throw ProtocolError.invalidMessage }

        // Parse field count from header
        guard data.count >= 6 else { throw ProtocolError.invalidMessage }
        let fieldCount: Int16 = data.withUnsafeBytes { ptr in
            let raw = ptr.load(fromByteOffset: 6, as: Int16.self)
            return Int16(bigEndian: raw)
        }

        // Calculate authenticated region size
        // Each field has a 3-byte overhead (tag + length prefix)
        // This multiplication can overflow for large fieldCount values
        let fieldOverhead: Int16 = 3
        let totalFieldOverhead = fieldCount &* fieldOverhead  // wrapping multiply

        // Convert to compute final authenticated length
        // totalFieldOverhead could be negative due to overflow!
        let payloadStart = Int(headerLen) + 4  // 4 bytes for header length prefix
        let payloadSize = data.count - payloadStart - 32  // subtract HMAC

        // authenticatedLength = header region + payload accounting
        let authenticatedLength = Int(totalFieldOverhead) + payloadStart + payloadSize

        // Safety check: must be positive and within message bounds
        guard authenticatedLength > 0 && authenticatedLength <= data.count - 32 else {
            // Fallback: authenticate everything except HMAC
            return data.count - 32
        }

        return authenticatedLength
    }

    /// Verify HMAC-SHA256 over the authenticated region
    private func verifyAuthenticity(data: Data) throws -> Bool {
        guard data.count >= 36 else { throw ProtocolError.invalidMessage } // min: 4 header + 32 HMAC

        let authLen = try computeAuthenticatedLength(data: data)
        let authenticatedRegion = data.prefix(authLen)
        let providedHMAC = data.suffix(32)

        // Use constant-time comparison via CryptoKit
        let expectedHMAC = HMAC<SHA256>.authenticationCode(
            for: authenticatedRegion,
            using: config.secret
        )

        return HMAC<SHA256>.isValidAuthenticationCode(
            providedHMAC,
            authenticating: authenticatedRegion,
            using: config.secret
        )
    }

    /// Parse and verify a complete protocol message
    func parseMessage(data: Data) throws -> ParsedMessage {
        guard data.count <= config.maxMessageSize else {
            throw ProtocolError.messageTooLarge
        }

        // Step 1: Verify authentication
        guard try verifyAuthenticity(data: data) else {
            throw ProtocolError.authenticationFailed
        }

        // Step 2: Parse header
        let headerLen = Int(data.withUnsafeBytes { ptr in
            Int32(bigEndian: ptr.load(fromByteOffset: 0, as: Int32.self))
        })

        guard headerLen >= 4 else { throw ProtocolError.invalidMessage }

        let version = data[4]
        guard version == config.protocolVersion else {
            throw ProtocolError.unsupportedVersion
        }

        let flags = data[5]
        let fieldCount = Int(data.withUnsafeBytes { ptr in
            Int16(bigEndian: ptr.load(fromByteOffset: 6, as: Int16.self))
        })

        // Step 3: Parse fields
        var fields: [(tag: UInt8, data: Data)] = []
        var offset = 8 // after version + flags + fieldCount

        for _ in 0..<fieldCount {
            guard offset + 3 <= 4 + headerLen else { break }
            let tag = data[offset]
            let fieldLen = Int(data.withUnsafeBytes { ptr in
                UInt16(bigEndian: ptr.load(fromByteOffset: offset + 1, as: UInt16.self))
            })
            offset += 3
            guard offset + fieldLen <= 4 + headerLen else { break }
            fields.append((tag: tag, data: data[offset..<offset+fieldLen]))
            offset += fieldLen
        }

        // Step 4: Extract payload
        let payloadStart = 4 + headerLen
        let payloadEnd = data.count - 32
        let payload = data[payloadStart..<payloadEnd]

        return ParsedMessage(
            version: version,
            flags: flags,
            fields: fields,
            payload: payload
        )
    }
}
